<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.pyusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Tier 4','Tier 3','Tier 2','Tier 1']
const values=computed(()=>dataset.value==='A'?[24,50,75,100]:dataset.value==='B'?[10,35,65,90]:dataset.value==='ties'?[40,40,40,40]:[0,0,0,0])
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="pyusage-demo" aria-label="Local pyramid chart example"><p>Synthetic capacity units by ordered tier. Equal-height centered bars encode magnitude by full width on a fixed 0–100 scale. These are not shares, nested populations or a conversion funnel.</p><div class="pyusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="ties">Equal tiers</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="pyusage-card"><template v-if="state==='ready'"><svg viewBox="0 0 320 250" role="img" aria-label="Four ordered centered bars. Full width equals capacity on fixed zero to one hundred domain, not half width."><line class="pyusage-guide" x1="40" x2="40" y1="24" y2="203"/><line class="pyusage-guide" x1="160" x2="160" y1="24" y2="203"/><line class="pyusage-guide" x1="280" x2="280" y1="24" y2="203"/><template v-for="(v,i) in values" :key="i"><rect v-if="v>0" class="pyusage-bar" :class="{selected:selected===i}" :x="160-v*1.2" :y="28+i*44" :width="v*2.4" height="28" :data-index="i" data-cm="fade"/><line v-else class="pyusage-zero" x1="160" x2="160" :y1="28+i*44" :y2="56+i*44"/><text class="pyusage-label" x="160" :y="22+i*44" text-anchor="middle">{{ labels[i] }} · {{ v }}</text></template><text x="160" y="224" text-anchor="middle">Full width 240 = 100 units · center is not a baseline</text><text x="160" y="242" text-anchor="middle">Equal heights; no triangular area encoding</text></svg><div role="group" aria-label="Select tier" class="pyusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }} capacity units; full width {{ (values[selected]*2.4).toFixed(1) }} SVG units. Fixed domain 0–100; no percentage of total.</p><table class="pyusage-data"><caption>Exact capacity and full widths, dataset {{ dataset }}</caption><thead><tr><th scope="col">Tier</th><th scope="col">Capacity</th><th scope="col">Width</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ values[i] }}</td><td>{{ (values[i]*2.4).toFixed(1) }}</td></tr></tbody></table></template><p v-else role="status" class="pyusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values and bars are withheld.':'No tier records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>


.pyusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.pyusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.pyusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.pyusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.pyusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.pyusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.pyusage-demo svg{display:block;width:100%;height:auto;max-height:320px;margin:16px 0}.pyusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.pyusage-demo .pyusage-total{fill:var(--vp-c-text-1);font-size:24px;font-weight:700}.pyusage-choices{display:flex;gap:6px;flex-wrap:wrap}.pyusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.pyusage-choices span{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.pyusage-data{display:table!important;width:100%;font-size:12px}.pyusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.pyusage-data :is(td,th){padding:6px!important}.pyusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}

.pyusage-guide{stroke:var(--vp-c-divider);stroke-dasharray:3 3}.pyusage-bar{fill:var(--vp-c-brand-1);opacity:.6}.pyusage-bar.selected{opacity:1;stroke:var(--vp-c-text-1);stroke-width:2}.pyusage-zero{stroke:var(--vp-c-text-1);stroke-width:3}.pyusage-demo svg .pyusage-label{fill:var(--vp-c-text-1);font-size:11px}
</style>
